      if ((filter === 'open' && checkbox.checked) ||
          (filter === 'completed' && !checkbox.checked)) {
        checkbox.closest('[data-testid="task-row"]').remove();
      }
    } catch {
      checkbox.checked = !checkbox.checked;
      error.hidden = false;
    }
